<?php
require_once __DIR__ . "/../includes/functions.php";
require_once __DIR__ . "/../config/koneksi.php";
require_once __DIR__ . "/../includes/orders.php";
expire_orders($conn);
require_role(["admin"]);
$start = (string) ($_GET["mulai"] ?? date("Y-m-d"));
$end = (string) ($_GET["akhir"] ?? date("Y-m-d"));
if (!preg_match("/^\\d{4}-\\d{2}-\\d{2}$/", $start) || !preg_match("/^\\d{4}-\\d{2}-\\d{2}$/", $end) || $start > $end) {
    http_response_code(422);
    exit("Rentang tanggal tidak valid.");
}
$summary = one("SELECT (SELECT COUNT(*) FROM orders WHERE created_at >= ? AND created_at < DATE_ADD(?, INTERVAL 1 DAY)) AS order_count, (SELECT COALESCE(SUM(total), 0) FROM orders WHERE paid_at >= ? AND paid_at < DATE_ADD(?, INTERVAL 1 DAY)) AS revenue, (SELECT COALESCE(SUM(total), 0) FROM orders WHERE refunded_at >= ? AND refunded_at < DATE_ADD(?, INTERVAL 1 DAY)) AS refunds", "ssssss", [$start, $end, $start, $end, $start, $end]);
$mix = all_rows("SELECT order_type, COUNT(*) AS order_count FROM orders WHERE created_at >= ? AND created_at < DATE_ADD(?, INTERVAL 1 DAY) GROUP BY order_type", "ss", [$start, $end]);
$best = all_rows("SELECT oi.product_name, SUM(oi.qty) AS qty_sold FROM order_items oi JOIN orders o ON o.order_id = oi.order_id WHERE o.paid_at >= ? AND o.paid_at < DATE_ADD(?, INTERVAL 1 DAY) GROUP BY oi.product_name ORDER BY qty_sold DESC LIMIT 10", "ss", [$start, $end]);
$daily = all_rows("SELECT d.report_date, (SELECT COUNT(*) FROM orders c WHERE DATE(c.created_at) = d.report_date) AS order_count, (SELECT COALESCE(SUM(p.total), 0) FROM orders p WHERE DATE(p.paid_at) = d.report_date) AS revenue, (SELECT COALESCE(SUM(r.total), 0) FROM orders r WHERE DATE(r.refunded_at) = d.report_date) AS refunds FROM (SELECT DATE(created_at) AS report_date FROM orders WHERE created_at >= ? AND created_at < DATE_ADD(?, INTERVAL 1 DAY) UNION SELECT DATE(paid_at) FROM orders WHERE paid_at >= ? AND paid_at < DATE_ADD(?, INTERVAL 1 DAY) UNION SELECT DATE(refunded_at) FROM orders WHERE refunded_at >= ? AND refunded_at < DATE_ADD(?, INTERVAL 1 DAY)) d ORDER BY d.report_date DESC", "ssssss", [$start, $end, $start, $end, $start, $end]);
$monthly = all_rows("SELECT d.report_month, (SELECT COUNT(*) FROM orders c WHERE DATE_FORMAT(c.created_at, '%Y-%m') = d.report_month) AS order_count, (SELECT COALESCE(SUM(p.total), 0) FROM orders p WHERE DATE_FORMAT(p.paid_at, '%Y-%m') = d.report_month) AS revenue, (SELECT COALESCE(SUM(r.total), 0) FROM orders r WHERE DATE_FORMAT(r.refunded_at, '%Y-%m') = d.report_month) AS refunds FROM (SELECT DATE_FORMAT(created_at, '%Y-%m') AS report_month FROM orders WHERE created_at >= ? AND created_at < DATE_ADD(?, INTERVAL 1 DAY) UNION SELECT DATE_FORMAT(paid_at, '%Y-%m') FROM orders WHERE paid_at >= ? AND paid_at < DATE_ADD(?, INTERVAL 1 DAY) UNION SELECT DATE_FORMAT(refunded_at, '%Y-%m') FROM orders WHERE refunded_at >= ? AND refunded_at < DATE_ADD(?, INTERVAL 1 DAY)) d ORDER BY d.report_month DESC", "ssssss", [$start, $end, $start, $end, $start, $end]);
$shifts = all_rows("SELECT s.shift_id, l.username, l.nama, s.opened_at, s.closed_at, s.opening_cash, s.closing_cash, COUNT(o.order_id) AS paid_orders, COALESCE(SUM(CASE WHEN o.paid_at >= ? AND o.paid_at < DATE_ADD(?, INTERVAL 1 DAY) THEN o.total ELSE 0 END), 0) AS shift_revenue, COALESCE(SUM(CASE WHEN o.refunded_at >= ? AND o.refunded_at < DATE_ADD(?, INTERVAL 1 DAY) THEN o.total ELSE 0 END), 0) AS shift_refunds FROM cashier_shifts s JOIN login l ON l.user_id = s.cashier_id LEFT JOIN orders o ON o.cashier_shift_id = s.shift_id WHERE s.opened_at >= ? AND s.opened_at < DATE_ADD(?, INTERVAL 1 DAY) GROUP BY s.shift_id, l.username, l.nama, s.opened_at, s.closed_at, s.opening_cash, s.closing_cash ORDER BY s.opened_at DESC LIMIT 200", "ssssss", [$start, $end, $start, $end, $start, $end]);
$pageTitle = "Admin · Laporan";
require __DIR__ . "/../includes/header.php";
require __DIR__ . "/_nav.php";
?>
<section><h1>Laporan penjualan</h1><form method="get" class="form-grid"><label>Mulai<input type="date" name="mulai" value="<?= e($start) ?>"></label><label>Akhir<input type="date" name="akhir" value="<?= e($end) ?>"></label><button>Tampilkan</button></form>
<div class="panel"><p>Periode: <?= e($start) ?> s.d. <?= e($end) ?></p><p>Jumlah pesanan: <?= e($summary["order_count"]) ?></p><p>Pemasukan dari pembayaran: Rp <?= e(number_format((int) $summary["revenue"], 0, ",", ".")) ?></p><p>Refund tercatat (manual oleh kasir): Rp <?= e(number_format((int) $summary["refunds"], 0, ",", ".")) ?></p><p>Pemasukan bersih: Rp <?= e(number_format((int) $summary["revenue"] - (int) $summary["refunds"], 0, ",", ".")) ?></p><h2>Perbandingan tipe</h2><ul><?php foreach ($mix as $row): ?><li><?= e($row["order_type"] === "dine_in" ? "Makan di tempat" : "Takeaway") ?>: <?= e($row["order_count"]) ?></li><?php endforeach; ?></ul><h2>Produk terlaris</h2><ol><?php foreach ($best as $row): ?><li><?= e($row["product_name"]) ?> — <?= e($row["qty_sold"]) ?> item</li><?php endforeach; ?></ol></div>
<div class="panel table-wrap"><h2>Catatan harian</h2><table><thead><tr><th>Tanggal</th><th>Pesanan</th><th>Pemasukan</th><th>Refund</th></tr></thead><tbody><?php foreach ($daily as $row): ?><tr><td><?= e($row["report_date"]) ?></td><td><?= e($row["order_count"]) ?></td><td>Rp <?= e(number_format((int) $row["revenue"], 0, ",", ".")) ?></td><td>Rp <?= e(number_format((int) $row["refunds"], 0, ",", ".")) ?></td></tr><?php endforeach; ?></tbody></table></div>
<div class="panel table-wrap"><h2>Rekap bulanan</h2><table><thead><tr><th>Bulan</th><th>Pesanan</th><th>Pemasukan</th><th>Refund</th></tr></thead><tbody><?php foreach ($monthly as $row): ?><tr><td><?= e($row["report_month"]) ?></td><td><?= e($row["order_count"]) ?></td><td>Rp <?= e(number_format((int) $row["revenue"], 0, ",", ".")) ?></td><td>Rp <?= e(number_format((int) $row["refunds"], 0, ",", ".")) ?></td></tr><?php endforeach; ?></tbody></table></div>
<div class="panel table-wrap"><h2>Sesi kasir pada periode</h2><table><thead><tr><th>Kasir</th><th>Buka</th><th>Tutup</th><th>Modal awal</th><th>Kas akhir</th><th>Jumlah order</th><th>Pemasukan bersih shift</th></tr></thead><tbody><?php foreach ($shifts as $shift): ?><tr><td><?= e($shift["nama"] . " (" . $shift["username"] . ")") ?></td><td><?= e($shift["opened_at"]) ?></td><td><?= e($shift["closed_at"] ?? "Masih berjalan") ?></td><td>Rp <?= e(number_format((int) $shift["opening_cash"], 0, ",", ".")) ?></td><td><?= $shift["closing_cash"] === null ? "—" : "Rp " . e(number_format((int) $shift["closing_cash"], 0, ",", ".")) ?></td><td><?= e($shift["paid_orders"]) ?></td><td>Rp <?= e(number_format((int) $shift["shift_revenue"] - (int) $shift["shift_refunds"], 0, ",", ".")) ?></td></tr><?php endforeach; ?></tbody></table></div>
</section>
<?php require __DIR__ . "/../includes/footer.php"; ?>
